#include <iostream>
#include <thread>
#include <mutex>

class Singleton {
private:
    static Singleton* pInstance;
    static std::mutex mtx;
    int data;

    Singleton() : data(42) {
        // Simulate construction work
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Singleton constructed\n";
    }

public:
    // BROKEN DCLP (DO NOT USE IN PRODUCTION)
    static Singleton* instanceDCLP_Broken() {
        if (pInstance == nullptr) {          // Check 1: No lock
            std::lock_guard<std::mutex> lock(mtx);
            if (pInstance == nullptr) {      // Check 2: With lock
                // Problem: These 3 steps can be reordered:
                // 1. Allocate memory
                // 2. Construct object
                // 3. Assign to pInstance
                // Compiler may do: 1->3->2, exposing unconstructed object!
                pInstance = new Singleton();
            }
        }
        return pInstance;
    }

    // SAFE: Simple lock-based approach
    static Singleton* instanceSafe() {
        std::lock_guard<std::mutex> lock(mtx);
        if (pInstance == nullptr) {
            pInstance = new Singleton();
        }
        return pInstance;
    }

    // SAFE: C++11 thread-safe local static (Meyers Singleton)
    static Singleton& instanceMeyers() {
        static Singleton instance;  // Thread-safe in C++11+
        return instance;
    }

    int getData() const { return data; }
};

Singleton* Singleton::pInstance = nullptr;
std::mutex Singleton::mtx;

int main() {
    std::cout << "DCLP is broken due to instruction reordering.\n";
    std::cout << "Use Meyers Singleton (local static) for thread safety.\n";

    // Safe approach
    Singleton& s = Singleton::instanceMeyers();
    std::cout << "Data: " << s.getData() << "\n";

    return 0;
}
